svg.script:
/*  */
(function() {
  // 5 Target Data Definitions (Clinical parameters and Straits)
  var targetsData = {
    1: {
      strait: "ARO 1: ENTRADA (Estreito Superior)",
      straitColor: "var(--a12p13-entrada)",
      straitId: "a12p13-strait-1",
      title: "ALVO 1: PROMONTÓRIO SACRAL (S1)",
      question: "Pergunta clínica: É alcançável pelo toque vaginal?",
      normalVal: "Achado: NÃO ALCANÇÁVEL",
      normalDesc: "Conjugado Diagonal >= 11,5 cm (Obstétrico >= 10 cm). Insinuação livre.",
      alteredVal: "Achado: ALCANÇÁVEL FACILMENTE",
      alteredDesc: "Conjugado Diagonal < 11,5 cm. Risco de distocia no plano de entrada.",
      handTransform: "translate(165, 115) rotate(-35)",
      insetT4Opacity: "0.2",
      insetT5Opacity: "0.2"
    },
    2: {
      strait: "ARO 2: MEIO (Estreito Médio)",
      straitColor: "var(--a12p13-meio)",
      straitId: "a12p13-strait-2",
      title: "ALVO 2: ESPINHAS ISQUIÁTICAS",
      question: "Pergunta clínica: Apresentam-se proeminentes ao toque?",
      normalVal: "Achado: ROMBAS / POUCO PROEMINENTES",
      normalDesc: "Diâmetro Interespinha >= 10,0 cm. Paredes pélvicas paralelas.",
      alteredVal: "Achado: PROEMINENTES / PONTIAGUDAS",
      alteredDesc: "Diâmetro Interespinha < 10,0 cm. Risco de parada de descida no meio.",
      handTransform: "translate(260, 240) rotate(-15)",
      insetT4Opacity: "0.2",
      insetT5Opacity: "0.2"
    },
    3: {
      strait: "ARO 2: MEIO (Estreito Médio)",
      straitColor: "var(--a12p13-meio)",
      straitId: "a12p13-strait-2",
      title: "ALVO 3: CONCAVIDADE SACRAL",
      question: "Pergunta clínica: Sacro é curvo e profundo?",
      normalVal: "Achado: CURVATURA REGULAR E PROFUNDA",
      normalDesc: "Sacro escavado permite a rotação interna da apresentação fetal.",
      alteredVal: "Achado: SACRO PLANO / RETILÍNEO",
      alteredDesc: "Redução do diâmetro anteroposterior médio. Dificulta a rotação.",
      handTransform: "translate(150, 225) rotate(-45)",
      insetT4Opacity: "0.2",
      insetT5Opacity: "0.2"
    },
    4: {
      strait: "ARO 3: SAÍDA (Estreito Inferior)",
      straitColor: "var(--a12p13-saida)",
      straitId: "a12p13-strait-3",
      title: "ALVO 4: ÂNGULO SUBPÚBICO",
      question: "Pergunta clínica: Ângulo do arco subpúbico é >= 90°?",
      normalVal: "Achado: ARCO AMPLO (>= 90°)",
      normalDesc: "Acomoda confortavelmente 2 dedos abertos sob a sínfise púbica.",
      alteredVal: "Achado: ARCO AGUDO (< 90°)",
      alteredDesc: "Estreitamento do arco pubiano. Risco de deflexão e distocia de saída.",
      handTransform: "translate(320, 280) rotate(10)",
      insetT4Opacity: "1.0",
      insetT5Opacity: "0.2"
    },
    5: {
      strait: "ARO 3: SAÍDA (Estreito Inferior)",
      straitColor: "var(--a12p13-saida)",
      straitId: "a12p13-strait-3",
      title: "ALVO 5: TUBEROSIDADES ISQUIÁTICAS",
      question: "Pergunta clínica: O punho fechado cabe entre as tuberosidades?",
      normalVal: "Achado: PUNHO CABE (>= 8,5 cm)",
      normalDesc: "Diâmetro intertuberoso amplo. Permitirá o desprendimento cefálico.",
      alteredVal: "Achado: PUNHO NÃO CABE (< 8,5 cm)",
      alteredDesc: "Estreitamento do plano de saída vaginal. Indica distocia de saída.",
      handTransform: "translate(300, 370) rotate(30)",
      insetT4Opacity: "0.2",
      insetT5Opacity: "1.0"
    }
  };

  var activeTarget = 1;

  function setActiveTarget(id) {
    if (!targetsData[id]) return;
    activeTarget = id;

    // 1. Update Target Groups Active Classes
    for (var t = 1; t <= 5; t++) {
      var tg = document.getElementById("a12p13-target-" + t);
      var btn = document.getElementById("a12p13-btn-" + t);
      var trow = document.getElementById("a12p13-trow-" + t);

      if (t === id) {
        if (tg) tg.classList.add("is-active");
        if (btn) btn.classList.add("is-active");
        if (trow) trow.classList.add("is-active");
      } else {
        if (tg) tg.classList.remove("is-active");
        if (btn) btn.classList.remove("is-active");
        if (trow) trow.classList.remove("is-active");
      }
    }

    // 2. Update Pelvic Strait Active Highlight
    var activeStraitId = targetsData[id].straitId;
    for (var s = 1; s <= 3; s++) {
      var straitEl = document.getElementById("a12p13-strait-" + s);
      if (straitEl) {
        if ("a12p13-strait-" + s === activeStraitId) {
          straitEl.classList.add("is-active");
        } else {
          straitEl.classList.remove("is-active");
        }
      }
    }

    // 3. Move Hand Group to Anatomical Target
    var handGroup = document.getElementById("a12p13-hand-group");
    if (handGroup) {
      handGroup.setAttribute("transform", targetsData[id].handTransform);
    }

    // 4. Update Inset Graphics Opacity
    var insetT4 = document.getElementById("a12p13-inset-t4-graphic");
    var insetT5 = document.getElementById("a12p13-inset-t5-graphic");
    if (insetT4) insetT4.setAttribute("opacity", targetsData[id].insetT4Opacity);
    if (insetT5) insetT5.setAttribute("opacity", targetsData[id].insetT5Opacity);

    // 5. Update Reading Panel Texts
    var badgeBg = document.getElementById("a12p13-strait-badge-bg");
    var badgeTxt = document.getElementById("a12p13-strait-badge-txt");
    var tTitle = document.getElementById("a12p13-target-title");
    var tQuestion = document.getElementById("a12p13-target-question");
    var nVal = document.getElementById("a12p13-normal-val");
    var nDesc = document.getElementById("a12p13-normal-desc");
    var aVal = document.getElementById("a12p13-altered-val");
    var aDesc = document.getElementById("a12p13-altered-desc");

    if (badgeBg) badgeBg.setAttribute("fill", targetsData[id].straitColor);
    if (badgeTxt) badgeTxt.textContent = targetsData[id].strait;
    if (tTitle) tTitle.textContent = targetsData[id].title;
    if (tQuestion) tQuestion.textContent = targetsData[id].question;
    if (nVal) nVal.textContent = targetsData[id].normalVal;
    if (nDesc) nDesc.textContent = targetsData[id].normalDesc;
    if (aVal) aVal.textContent = targetsData[id].alteredVal;
    if (aDesc) aDesc.textContent = targetsData[id].alteredDesc;
  }

  // Bind Clicks and Keydown to Targets and Buttons
  function bindEvents() {
    for (var i = 1; i <= 5; i++) {
      (function(targetId) {
        var tg = document.getElementById("a12p13-target-" + targetId);
        var btn = document.getElementById("a12p13-btn-" + targetId);
        var trow = document.getElementById("a12p13-trow-" + targetId);

        var handler = function(e) {
          e.preventDefault();
          setActiveTarget(targetId);
        };

        if (tg) {
          tg.addEventListener("click", handler);
          tg.addEventListener("keydown", function(e) {
            if (e.key === "Enter" || e.key === " ") handler(e);
          });
        }
        if (btn) btn.addEventListener("click", handler);
        if (trow) {
          trow.style.cursor = "pointer";
          trow.addEventListener("click", handler);
        }
      })(i);
    }

    // Global Keyboard Navigation (1..5 and Left/Right Arrows)
    document.addEventListener("keydown", function(e) {
      if (e.key >= "1" && e.key <= "5") {
        setActiveTarget(parseInt(e.key, 10));
      } else if (e.key === "ArrowRight" || e.key === "ArrowDown") {
        var next = activeTarget >= 5 ? 1 : activeTarget + 1;
        setActiveTarget(next);
      } else if (e.key === "ArrowLeft" || e.key === "ArrowUp") {
        var prev = activeTarget <= 1 ? 5 : activeTarget - 1;
        setActiveTarget(prev);
      }
    });
  }

  // Initialize on load
  bindEvents();
  setActiveTarget(1);
})();
/*  */
